// Parse the incoming Telegram update and classify the intent.
const item = $input.first().json;

let chatId = null;
let userId = null;
let messageId = null;
let intent = 'unknown';
let payload = {};
let rawText = '';
let callbackId = null;

if (item.message) {
  chatId = item.message.chat.id;
  userId = item.message.from?.id ?? null;
  messageId = item.message.message_id;
  rawText = (item.message.text || '').trim();
  const lower = rawText.toLowerCase();
  if (lower.startsWith('/start')) {
    intent = 'start';
  } else if (lower.startsWith('/learn')) {
    const url = rawText.replace(/^\/learn\s*/i, '').trim();
    if (!url || !/^https?:\/\//i.test(url)) {
      intent = 'learn_bad_url';
    } else {
      intent = 'learn';
      payload = { url };
    }
  } else if (lower.startsWith('/quiz')) {
    intent = 'quiz_menu';
  } else {
    intent = 'unknown';
  }
} else if (item.callback_query) {
  chatId = item.callback_query.message?.chat?.id;
  userId = item.callback_query.from?.id ?? null;
  messageId = item.callback_query.message?.message_id;
  callbackId = item.callback_query.id;
  const data = item.callback_query.data || '';
  if (data.startsWith('topic:')) {
    intent = 'topic_pick';
    payload = { materialId: data.slice('topic:'.length) };
  } else if (data.startsWith('answer:')) {
    const parts = data.slice('answer:'.length).split(':');
    intent = 'quiz_answer';
    payload = {
      questionIdx: parseInt(parts[0], 10),
      choiceIdx: parseInt(parts[1], 10),
    };
  }
}

return [{ json: { chatId, userId, messageId, callbackId, intent, payload, rawText } }];

// Extract title and clean text from raw HTML.
const prev = $('Parse Update').first().json;
const body = $input.first().json.data || $input.first().json.body || '';
const html = typeof body === 'string' ? body : JSON.stringify(body);

const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const title = (titleMatch ? titleMatch[1] : 'Untitled').replace(/\s+/g, ' ').trim();

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<\/(p|div|h\d|li|br|tr)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{2,}/g, '\n\n')
  .trim();

const excerpt = text.slice(0, 8000);
const short = text.length === 0;

return [{
  json: {
    chatId: prev.chatId,
    url: prev.payload.url,
    title,
    excerpt,
    short,
  }
}];

