// Persist the material and format the Telegram reply.
const aiItem = $input.first().json;
const prev = $('Extract Content').first().json;

// Robustly extract the JSON object from various openai node shapes.
let summary = null;
const candidates = [
  aiItem.message?.content,
  aiItem.choices?.[0]?.message?.content,
  aiItem.content,
  aiItem.text,
  aiItem.output,
  aiItem.response,
];
for (const c of candidates) {
  if (!c) continue;
  if (typeof c === 'object' && (c.key_points || c.title)) { summary = c; break; }
  if (typeof c === 'string') {
    const cleaned = c.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
    try { summary = JSON.parse(cleaned); break; } catch (_) {}
  }
}
if (!summary && typeof aiItem === 'object' && aiItem.key_points) summary = aiItem;
if (!summary) {
  return [{ json: {
    chatId: prev.chatId,
    text: '⚠️ I could not parse the Teacher\'s response. Please try a different URL.',
  } }];
}

const store = $getWorkflowStaticData('global');
store.materialsByChat = store.materialsByChat || {};
const chatKey = String(prev.chatId);
store.materialsByChat[chatKey] = store.materialsByChat[chatKey] || [];
const materialId = 'm' + Date.now().toString(36) + Math.floor(Math.random() * 1000).toString(36);
const record = {
  id: materialId,
  url: prev.url,
  title: (summary.title || prev.title || 'Untitled').slice(0, 80),
  excerpt: prev.excerpt,
  summary,
  createdAt: new Date().toISOString(),
};
store.materialsByChat[chatKey].unshift(record);
// Cap stored materials per chat (keep most recent 25)
if (store.materialsByChat[chatKey].length > 25) {
  store.materialsByChat[chatKey] = store.materialsByChat[chatKey].slice(0, 25);
}

const esc = s => String(s).replace(/[_*`\[\]]/g, c => '\\' + c);
const lines = [
  '📘 *' + esc(record.title) + '*',
  '_Difficulty: ' + esc(summary.difficulty || 'unknown') + '_',
  '',
  '*Key points:*'
];
(summary.key_points || []).slice(0, 7).forEach((p, i) => {
  lines.push((i + 1) + '. ' + esc(p));
});
lines.push('');
lines.push('*Main concepts:*');
(summary.main_concepts || []).slice(0, 6).forEach(c => {
  if (typeof c === 'string') {
    lines.push('• ' + esc(c));
  } else {
    lines.push('• *' + esc(c.term || c.name || '?') + '* — ' + esc(c.definition || c.desc || ''));
  }
});
lines.push('');
lines.push('_Tap the button below to take a quiz, or send `/quiz` later to pick from saved topics._');

return [{
  json: {
    chatId: prev.chatId,
    text: lines.join('\n'),
    reply_markup: {
      inline_keyboard: [[
        { text: '🎯 Quiz me on this', callback_data: 'topic:' + materialId }
      ]]
    }
  }
}];

// List saved materials for the current chat as a Telegram inline keyboard.
const prev = $input.first().json;
const store = $getWorkflowStaticData('global');
const chatKey = String(prev.chatId);
const list = (store.materialsByChat || {})[chatKey] || [];

if (list.length === 0) {
  return [{
    json: {
      chatId: prev.chatId,
      text: '📭 You have no saved materials yet.\n\nSend `/learn https://...` to add one.'
    }
  }];
}

const rows = list.slice(0, 12).map(m => ([{
  text: m.title.slice(0, 60),
  callback_data: 'topic:' + m.id
}]));

return [{
  json: {
    chatId: prev.chatId,
    text: '📚 *Pick a topic to quiz on:*',
    reply_markup: { inline_keyboard: rows }
  }
}];

// Pull the chosen material from store; pass excerpt to the Examiner.
const prev = $input.first().json;
const store = $getWorkflowStaticData('global');
const chatKey = String(prev.chatId);
const list = (store.materialsByChat || {})[chatKey] || [];
const material = list.find(m => m.id === prev.payload.materialId);
if (!material) {
  return [{ json: {
    chatId: prev.chatId,
    skip: true,
    text: '⚠️ That topic is no longer available. Send `/quiz` to see the current list.'
  } }];
}
return [{
  json: {
    chatId: prev.chatId,
    material,
    title: material.title,
    excerpt: material.excerpt,
  }
}];

// Parse the quiz, persist it, format question 1.
const aiItem = $input.first().json;
const loadCtx = $('Load Material').first().json;

let parsed = null;
const candidates = [
  aiItem.message?.content,
  aiItem.choices?.[0]?.message?.content,
  aiItem.content,
  aiItem.text,
  aiItem.output,
  aiItem.response,
];
for (const c of candidates) {
  if (!c) continue;
  if (typeof c === 'object' && c.questions) { parsed = c; break; }
  if (typeof c === 'string') {
    const cleaned = c.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
    try { parsed = JSON.parse(cleaned); break; } catch (_) {}
  }
}
if (!parsed && aiItem.questions) parsed = aiItem;
if (!parsed || !Array.isArray(parsed.questions) || parsed.questions.length === 0) {
  return [{ json: {
    chatId: loadCtx.chatId,
    text: '⚠️ The Examiner could not produce a valid quiz. Try `/quiz` again.'
  } }];
}

// Normalise: clamp to 5 questions, ensure 4 choices each.
const questions = parsed.questions.slice(0, 5).map(q => ({
  text: String(q.text || '').slice(0, 240),
  choices: (q.choices || []).slice(0, 4),
  correct_idx: typeof q.correct_idx === 'number' ? q.correct_idx : 0,
  explanation: String(q.explanation || '').slice(0, 400),
}));

const store = $getWorkflowStaticData('global');
store.quizzesByChat = store.quizzesByChat || {};
const chatKey = String(loadCtx.chatId);
store.quizzesByChat[chatKey] = {
  materialId: loadCtx.material.id,
  materialTitle: loadCtx.material.title,
  questions,
  answers: [],
  startedAt: new Date().toISOString(),
};

const q = questions[0];
const esc = s => String(s).replace(/[_*`\[\]]/g, c => '\\' + c);
const body = '*Quiz: ' + esc(loadCtx.material.title) + '*\n\n*Q1/' + questions.length + ':* ' + esc(q.text);

return [{
  json: {
    chatId: loadCtx.chatId,
    text: body,
    reply_markup: {
      inline_keyboard: q.choices.map((c, i) => ([{
        text: String.fromCharCode(65 + i) + '. ' + String(c).slice(0, 80),
        callback_data: 'answer:0:' + i
      }]))
    }
  }
}];

// Record the user's answer, then either send the next question or the final results.
const prev = $input.first().json;
const store = $getWorkflowStaticData('global');
const chatKey = String(prev.chatId);
const quiz = (store.quizzesByChat || {})[chatKey];
if (!quiz) {
  return [{ json: {
    done: true,
    chatId: prev.chatId,
    text: 'No active quiz. Send `/quiz` to start one.'
  } }];
}

const { questionIdx, choiceIdx } = prev.payload;
const q = quiz.questions[questionIdx];
if (!q) {
  return [{ json: {
    done: true,
    chatId: prev.chatId,
    text: '⚠️ Invalid quiz state. Send `/quiz` to start again.'
  } }];
}

// Idempotent: ignore re-answers for an already-recorded question.
if (quiz.answers[questionIdx]) {
  // No-op response
  return [{ json: {
    done: false,
    chatId: prev.chatId,
    text: '↩️ Already recorded that one — waiting for the next.',
    reply_markup: null
  } }];
}

quiz.answers[questionIdx] = {
  choiceIdx,
  chosen: q.choices[choiceIdx] ?? '?',
  correct: choiceIdx === q.correct_idx,
  question: q.text,
  correctAnswer: q.choices[q.correct_idx] ?? '?',
  explanation: q.explanation,
};

const nextIdx = questionIdx + 1;
if (nextIdx >= quiz.questions.length) {
  // Quiz complete — compute score.
  const correct = quiz.answers.filter(a => a && a.correct).length;
  const total = quiz.questions.length;
  const score = Math.round((correct / total) * 100);
  const wrongs = quiz.answers.map((a, i) => ({ i, ...a })).filter(a => !a.correct);
  return [{ json: {
    done: true,
    chatId: prev.chatId,
    quiz,
    score,
    correct,
    total,
    wrongs,
  } }];
}

const nq = quiz.questions[nextIdx];
const esc = s => String(s).replace(/[_*`\[\]]/g, c => '\\' + c);
return [{ json: {
  done: false,
  chatId: prev.chatId,
  text: '*Q' + (nextIdx + 1) + '/' + quiz.questions.length + ':* ' + esc(nq.text),
  reply_markup: {
    inline_keyboard: nq.choices.map((c, i) => ([{
      text: String.fromCharCode(65 + i) + '. ' + String(c).slice(0, 80),
      callback_data: 'answer:' + nextIdx + ':' + i
    }]))
  }
} }];

// Build the final results message and clear active quiz state.
const item = $input.first().json;
const store = $getWorkflowStaticData('global');
const chatKey = String(item.chatId);
if (store.quizzesByChat && store.quizzesByChat[chatKey]) {
  delete store.quizzesByChat[chatKey];
}

const esc = s => String(s).replace(/[_*`\[\]]/g, c => '\\' + c);
const lines = [
  '🏁 *Quiz complete — ' + item.score + '%*',
  esc(item.correct + '/' + item.total + ' correct on ' + (item.quiz?.materialTitle ?? 'this material')),
  '',
];

item.quiz.answers.forEach((a, i) => {
  if (!a) return;
  const mark = a.correct ? '✅' : '❌';
  lines.push(mark + ' *Q' + (i + 1) + '.* ' + esc(a.question));
  if (!a.correct) {
    lines.push('   Your answer: ' + esc(a.chosen));
    lines.push('   Correct: ' + esc(a.correctAnswer));
    if (a.explanation) lines.push('   _' + esc(a.explanation) + '_');
  }
  lines.push('');
});

lines.push('Send `/quiz` to try another topic, or `/learn <url>` to add new material.');

return [{ json: { chatId: item.chatId, text: lines.join('\n') } }];
